import * as THREE from '../vendor/three.module.js';
import {DetailBatch,roundedBox,material,surface} from '../visuals/model-kit.js';
const cylinder=new THREE.CylinderGeometry(1,1,1,7),up=new THREE.Vector3(0,1,0);
export class ExteriorKit{
 constructor(root,api){this.root=root;this.api=api;this.batch=new DetailBatch(root);this.solids=[];this.props=[];this.cameraBlocks=[];this.nightMaterials=[];}
 box(x,y,z,w,h,d,color,solid=false,angle=0,finish){const mat=typeof color==='string'?(finish?surface(color,finish):material(color)):color;this.batch.box(w,h,d,mat,x,y,z,angle);if(solid)this.solids.push({x,z,w,d,angle,bottom:y-h/2,top:y+h/2,walkable:h<2.2});}
 soft(x,y,z,w,h,d,color,solid=false){const o=new THREE.Object3D();o.position.set(x,y,z);o.updateMatrix();this.batch.add(roundedBox(w,h,d),material(color),o.matrix);if(solid)this.solids.push({x,z,w,d,bottom:y-h/2,top:y+h/2,walkable:h<2.2});}
 beam(a,b,r,color){const aa=new THREE.Vector3(...a),bb=new THREE.Vector3(...b),delta=bb.clone().sub(aa),o=new THREE.Object3D();o.position.copy(aa).add(bb).multiplyScalar(.5);o.quaternion.setFromUnitVectors(up,delta.clone().normalize());o.scale.set(r,delta.length(),r);o.updateMatrix();this.batch.add(cylinder,typeof color==='string'?material(color):color,o.matrix);}
 rail(a,b,y1,y2,color='#505853'){const len=Math.hypot(b[0]-a[0],b[1]-a[1]),n=Math.ceil(len/4);this.beam([a[0],y1+1.08,a[1]],[b[0],y2+1.08,b[1]],.06,color);for(let i=0;i<=n;i++){const f=i/n,x=THREE.MathUtils.lerp(a[0],b[0],f),z=THREE.MathUtils.lerp(a[1],b[1],f),y=THREE.MathUtils.lerp(y1,y2,f);this.beam([x,y,z],[x,y+1.1,z],.055,color);}const dx=b[0]-a[0],dz=b[1]-a[1];this.solids.push({x:(a[0]+b[0])/2,z:(a[1]+b[1])/2,w:.14,d:len,angle:Math.atan2(dx,dz),bottom:Math.min(y1,y2),top:Math.max(y1,y2)+1.08,walkable:false});}
 sign(text,x,z,y,w=8,angle=0){this.box(x,y+2.7,z,w,.95,.22,'#3f5148');for(const s of[-1,1])this.box(x+Math.cos(angle)*s*w*.36,y+1.3,z-Math.sin(angle)*s*w*.36,.13,2.6,.13,'#5b6559');for(const side of[-1,1]){const g=new THREE.Group();g.position.set(x,y+2.7,z);g.rotation.y=angle+(side<0?Math.PI:0);this.root.add(g);this.api.label(text,w-.28,.68,'#3f5148','#eee8cd',g,0,0,.125);} }
 bench(x,z,y,angle=0){for(const s of[-1,1])this.box(x+Math.cos(angle)*s*1.25,y+.43,z-Math.sin(angle)*s*1.25,.18,.8,.6,'#4b5050',true,angle);for(let i=0;i<5;i++)this.box(x,y+.87,z+(i-2)*.13,3.1,.12,.1,'#8b7657',true,angle,'wood');this.box(x,y+1.25,z-.35,3,.53,.1,'#8b7657',true,angle,'wood');}
 lamp(x,z,y){this.beam([x,y,z],[x,y+5.7,z],.1,'#465353');this.box(x,y+.12,z,.45,.24,.45,'#394645');this.box(x,y+5.85,z,.9,.15,.65,'#333f44');this.warm??=new THREE.MeshStandardMaterial({color:'#ffe9bd',emissive:'#ffd992',emissiveIntensity:1.7,roughness:.4});this.box(x,y+5.68,z,.7,.16,.43,this.warm);}
 bin(x,z,y,id){const g=new THREE.Group();g.position.set(x,y,z);this.root.add(g);const metal=surface('#536452','metal');this.api.box(.85,1.1,.72,metal,g,0,.55,0);this.api.box(.92,.13,.78,'#303d36',g,0,1.17,0);for(const s of[-1,1])this.api.box(.07,1.08,.73,'#a9b9a2',g,s*.36,.58,0);const c={x,z,w:.9,d:.8,bottom:y,top:y+1.3,walkable:true},p={id,g,hp:40,collider:c,baseY:y,type:'bin'};c.regionProp=p;this.solids.push(c);this.props.push(p);}
 mesh(geo,mat,name){const m=new THREE.Mesh(geo,mat);m.name=name;m.castShadow=m.receiveShadow=true;this.root.add(m);this.cameraBlocks.push(m);return m;}
 finish(){this.batch.finish();}
}
